import{_ as t,o,c as d,ae as r}from"./chunks/framework.YL6nI5ZP.js";const g=JSON.parse('{"title":"Technology Stack","description":"","frontmatter":{},"headers":[],"relativePath":"reference/03-technology-stack.md","filePath":"reference/03-technology-stack.md"}'),n={name:"reference/03-technology-stack.md"};function a(s,e,i,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h1><p>Every technology and framework in the project and its role — the UI, the map rendering, the meshers, the engine, the server, and the tooling.</p><h2 id="key-properties" tabindex="-1">Key properties <a class="header-anchor" href="#key-properties" aria-label="Permalink to &quot;Key properties&quot;">​</a></h2><p>From the project overview:</p><ul><li><strong>No backend.</strong> The only server is a trivial static-file + health endpoint server (<code>server.py</code>). No database, no build step for the UI, no bundler.</li><li><strong>No UI framework.</strong> The frontend is ~15,000 lines of dependency-free JavaScript (classic scripts + IIFEs) using Mapbox GL JS as the only heavyweight runtime library.</li><li><strong>WASM-embedded hydraulics.</strong> The OpenSWMM 6.0.0 engine is cross-compiled for <code>wasm32-emscripten</code> with vcpkg-managed C++ dependencies (Eigen, HDF5, nlohmann-json, SUNDIALS).</li><li><strong>Two simulation backends.</strong> A WASM engine path (1D + 1D/2D coupled) and an <strong>experimental WebGPU</strong> backend that re-implements the 2D explicit local-inertial solver as WGSL compute kernels and runs it in parallel to the WASM engine.</li><li><strong>Two mesh generators.</strong> A legacy <code>poly2tri</code>-based generator and the production <strong>Shewchuk Triangle WASM</strong> (npm <code>triangle-wasm</code>) pipeline.</li></ul><h2 id="stack-by-layer" tabindex="-1">Stack by layer <a class="header-anchor" href="#stack-by-layer" aria-label="Permalink to &quot;Stack by layer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Notes</th></tr></thead><tbody><tr><td>Language (UI)</td><td>Plain JavaScript (ES2020+, IIFEs)</td><td>No TypeScript, no modules, no bundler</td></tr><tr><td>Map rendering</td><td>Mapbox GL JS v3.1.2 (CDN)</td><td>3D terrain, buildings, GeoJSON sources, custom WebGL2 layers</td></tr><tr><td>Coordinate math</td><td>proj4js 2.9.0 (CDN)</td><td>UTM/projected → WGS84 on import</td></tr><tr><td>GIS parsers</td><td>shpjs 4.0.4, dxf-parser 1.1.2 (CDN)</td><td>Shapefile + DXF import</td></tr><tr><td>2D triangulation</td><td>poly2tri 1.5.0 (legacy) <strong>and</strong> triangle-wasm 1.0.0 (production, vendored)</td><td>Shewchuk Triangle port</td></tr><tr><td>Rasters</td><td>geotiff 2.1.3 (CDN)</td><td>Local DEM (GeoTIFF) sampling</td></tr><tr><td>Engine</td><td>OpenSWMM 6.0.0-alpha (C++20)</td><td>Compiled with Emscripten 6.x to WASM</td></tr><tr><td>C++ deps</td><td>eigen3, hdf5, nlohmann-json, sundials</td><td>via vcpkg, wasm32-emscripten triplet</td></tr><tr><td>Language (server)</td><td>Python 3 stdlib (<code>http.server</code>)</td><td>Zero dependencies</td></tr><tr><td>Language (tooling)</td><td>Node.js (≥20)</td><td>Bench/verify/harness scripts, <code>npm</code></td></tr><tr><td>CI / hosting</td><td>GitHub Actions → GitHub Pages</td><td>Static deploy only</td></tr></tbody></table><h2 id="cdn-dependencies" tabindex="-1">CDN dependencies <a class="header-anchor" href="#cdn-dependencies" aria-label="Permalink to &quot;CDN dependencies&quot;">​</a></h2><p><strong>CDN dependencies loaded by <code>index.html</code></strong> (all pinned, CSP-restricted to <code>api.mapbox.com</code>, <code>cdn.jsdelivr.net</code>, <code>cdnjs.cloudflare.com</code>, <code>unpkg.com</code>, <code>maps.googleapis.com</code>): <code>mapbox-gl-js@3.1.2</code>, <code>proj4js@2.9.0</code>, <code>shpjs@4.0.4</code>, <code>dxf-parser@1.1.2</code>, <code>poly2tri@1.5.0</code>, <code>geotiff@2.1.3</code>, and (optionally) the Google Maps JS API.</p>',9)])])}const m=t(n,[["render",a]]);export{g as __pageData,m as default};
